def orfs(s, minaa=60):
    out=[]
    for strand,ss in ((1,s),(-1,rcomp(s))):
        for f in range(3):
            t=translate(ss[f:])
            i=0
            while i<len(t):
                if t[i]=='M':
                    j=t.find('*',i)
                    if j==-1: j=len(t)
                    if j-i>=minaa:
                        if strand==1: st=f+i*3; en=f+j*3
                        else: en=n-f-i*3; st=n-f-j*3
                        out.append((st,en,strand,j-i, t[i:j]))
                    i=j+1
                else: i+=1
    return out
